insert into public.courses
  (id, title, description, instructor, category, level, accent, icon, faculty, department, start_date, price)
values
  ('faculty-of-technology-software-development-100l-frontend-development', 'Frontend Development', 'Frontend Development teaches students how to build the visible parts of websites and web applications. Students learn HTML for structure, CSS for styling, JavaScript for interactivity, responsive design, accessibility, and component-based frameworks. The course emphasizes creating usable interfaces that work across desktop computers, tablets, and mobile devices.', '', 'Software Development', '100L', 'indigo', 'code', 'Faculty of Technology', 'Software Development', '2026-11-02', 15000),
  ('faculty-of-technology-software-development-100l-backend-development', 'Backend Development', 'Backend Development introduces the server-side technologies that power applications. Students learn how to process requests, implement business logic, authenticate users, manage databases, and protect sensitive information. Topics include server frameworks, application architecture, error handling, validation, and deployment. Practical exercises help students build reliable services that support frontend applications.', '', 'Software Development', '100L', 'indigo', 'code', 'Faculty of Technology', 'Software Development', '2026-11-02', 15500),
  ('faculty-of-technology-software-development-100l-full-stack-development', 'Full-Stack Development', 'Full-Stack Development combines frontend and backend programming to create complete applications. Students learn how interfaces communicate with servers, how databases store information, and how authentication protects accounts. Practical projects cover application architecture, API integration, validation, testing, and deployment, enabling learners to develop applications from the user interface through to the database.', '', 'Software Development', '100L', 'indigo', 'code', 'Faculty of Technology', 'Software Development', '2026-11-02', 16000),
  ('faculty-of-technology-software-development-100l-mobile-app-development', 'Mobile App Development', 'Mobile App Development focuses on creating applications for smartphones and tablets. Students explore mobile interface design, navigation, device capabilities, data storage, networking, and application performance. They may use native technologies or cross-platform frameworks. Practical projects teach students to develop, test, debug, and prepare mobile applications for distribution.', '', 'Software Development', '100L', 'indigo', 'code', 'Faculty of Technology', 'Software Development', '2026-11-02', 16500),
  ('faculty-of-technology-software-development-100l-desktop-application-development', 'Desktop Application Development', 'Desktop Application Development teaches students to create software that runs on personal computers. Topics include graphical user interfaces, file management, local databases, operating-system integration, application security, and packaging. Students learn to design applications for Windows, macOS, or Linux, while developing practical skills in debugging, usability, performance, and software maintenance.', '', 'Software Development', '100L', 'indigo', 'code', 'Faculty of Technology', 'Software Development', '2026-11-02', 17000),
  ('faculty-of-technology-software-development-100l-game-development', 'Game Development', 'Game Development introduces the programming, design, and production techniques used to create digital games. Students explore game mechanics, player interaction, physics, animation, sound, level design, and game engines. Practical assignments encourage learners to build playable prototypes, test gameplay, optimize performance, and understand the collaboration required in game production.', '', 'Software Development', '100L', 'indigo', 'code', 'Faculty of Technology', 'Software Development', '2026-11-02', 17500),
  ('faculty-of-technology-software-development-100l-api-development', 'API Development', 'API Development teaches students how to create interfaces that allow software systems to communicate. Topics include REST APIs, HTTP methods, request and response formats, authentication, authorization, validation, documentation, and error handling. Students build services that exchange data securely between applications and learn how to test, version, maintain, and integrate APIs.', '', 'Software Development', '100L', 'indigo', 'code', 'Faculty of Technology', 'Software Development', '2026-11-02', 18000),
  ('faculty-of-technology-software-development-100l-software-testing-and-quality-assurance', 'Software Testing and Quality Assurance', 'Software Testing and Quality Assurance teaches students how to verify that applications behave as expected. Learners explore test planning, manual testing, automated testing, unit tests, integration tests, regression testing, and defect reporting. Practical exercises develop skills in identifying bugs, evaluating requirements, improving reliability, and maintaining software quality throughout development.', '', 'Software Development', '100L', 'indigo', 'code', 'Faculty of Technology', 'Software Development', '2026-11-02', 18500),
  ('faculty-of-technology-computer-science-100l-algorithms-and-data-structures', 'Algorithms and Data Structures', 'This course explores methods for organizing data and solving computational problems efficiently. Students study arrays, linked lists, stacks, queues, trees, graphs, sorting, searching, and algorithm analysis. Practical programming exercises compare different approaches using time and memory complexity, helping learners choose suitable data structures and algorithms for real-world software applications.', '', 'Computer Science', '100L', 'indigo', 'code', 'Faculty of Technology', 'Computer Science', '2026-11-02', 19000),
  ('faculty-of-technology-computer-science-100l-programming-languages', 'Programming Languages', 'Programming Languages introduces the principles and characteristics of languages used to develop software. Students examine syntax, data types, variables, control structures, functions, object-oriented programming, and language paradigms. They also explore how interpreters and compilers work, compare programming languages, and learn how language selection affects application development, maintainability, and performance.', '', 'Computer Science', '100L', 'indigo', 'code', 'Faculty of Technology', 'Computer Science', '2026-11-02', 19500),
  ('faculty-of-technology-computer-science-100l-operating-systems', 'Operating Systems', 'Operating Systems examines the software that manages computer hardware and application resources. Students learn about processes, threads, memory management, file systems, scheduling, device management, and access permissions. Practical exercises introduce command-line tools and system monitoring, helping learners understand how operating systems coordinate resources and support multiple applications securely.', '', 'Computer Science', '100L', 'indigo', 'code', 'Faculty of Technology', 'Computer Science', '2026-11-02', 20000),
  ('faculty-of-technology-computer-science-100l-theory-of-computation', 'Theory of Computation', 'Theory of Computation explores the mathematical foundations of computing. Students study formal languages, finite automata, regular expressions, grammars, computability, and computational complexity. The course explains which problems computers can solve and how resource requirements affect solutions. Exercises develop logical reasoning and help learners understand the theoretical limits of algorithms.', '', 'Computer Science', '100L', 'indigo', 'code', 'Faculty of Technology', 'Computer Science', '2026-11-02', 20500),
  ('faculty-of-technology-computer-science-100l-artificial-intelligence', 'Artificial Intelligence', 'This course introduces computer systems designed to perform tasks associated with intelligent behaviour. Students explore search algorithms, knowledge representation, reasoning, planning, decision-making, and introductory machine learning. Practical activities demonstrate how intelligent systems solve problems, interpret information, and support decisions, while discussions address limitations, reliability, fairness, and responsible AI development.', '', 'Computer Science', '100L', 'indigo', 'code', 'Faculty of Technology', 'Computer Science', '2026-11-02', 21000),
  ('faculty-of-technology-computer-science-100l-computer-architecture', 'Computer Architecture', 'Computer Architecture explains how computer hardware components work together to execute programs. Students study processors, registers, memory hierarchies, instruction sets, input/output systems, and data representation. The course examines how hardware design influences performance and energy consumption. Practical exercises may include assembly-language examples, processor simulations, and performance comparisons.', '', 'Computer Science', '100L', 'indigo', 'code', 'Faculty of Technology', 'Computer Science', '2026-11-02', 21500),
  ('faculty-of-technology-computer-science-100l-human-computer-interaction', 'Human-Computer Interaction', 'Human-Computer Interaction studies how people interact with computers and digital systems. Students explore usability, interface design, human behaviour, accessibility, user research, prototyping, and evaluation methods. Projects involve analysing user needs and testing interface designs, helping learners create technology that is understandable, efficient, inclusive, and appropriate for different users and environments.', '', 'Computer Science', '100L', 'indigo', 'code', 'Faculty of Technology', 'Computer Science', '2026-11-02', 22000),
  ('faculty-of-technology-computer-science-100l-computational-mathematics', 'Computational Mathematics', 'Computational Mathematics applies mathematical methods and computer-based techniques to solve complex problems. Students study numerical methods, linear algebra, mathematical modelling, optimization, and computational approximation. Practical exercises use programming tools to analyse data and calculate solutions that may be difficult to obtain manually, while considering accuracy, efficiency, and numerical error.', '', 'Computer Science', '100L', 'indigo', 'code', 'Faculty of Technology', 'Computer Science', '2026-11-02', 22500),
  ('faculty-of-technology-cybersecurity-100l-network-security', 'Network Security', 'Network Security teaches students how to protect communication networks from attacks and unauthorized access. Topics include firewalls, secure network configurations, intrusion detection, encryption, access controls, and traffic monitoring. Practical exercises focus on identifying weaknesses, understanding common network threats, and applying defensive measures to improve the security and reliability of network infrastructure.', '', 'Cybersecurity', '100L', 'indigo', 'code', 'Faculty of Technology', 'Cybersecurity', '2026-11-02', 23000),
  ('faculty-of-technology-cybersecurity-100l-application-security', 'Application Security', 'Application Security focuses on identifying and preventing vulnerabilities in software. Students learn secure coding, input validation, authentication, authorization, session management, dependency security, and security testing. They examine common application weaknesses and practise defensive development techniques. The course encourages integrating security checks throughout the software development lifecycle rather than treating security as a final step.', '', 'Cybersecurity', '100L', 'indigo', 'code', 'Faculty of Technology', 'Cybersecurity', '2026-11-02', 23500),
  ('faculty-of-technology-cybersecurity-100l-cloud-security', 'Cloud Security', 'Cloud Security examines methods for protecting applications, data, and infrastructure hosted by cloud providers. Students learn identity management, encryption, access policies, secure configurations, logging, and incident response. The course also introduces shared responsibility models and cloud security monitoring, helping learners understand how organizations reduce risks when using cloud-based computing resources.', '', 'Cybersecurity', '100L', 'indigo', 'code', 'Faculty of Technology', 'Cybersecurity', '2026-11-02', 24000),
  ('faculty-of-technology-cybersecurity-100l-ethical-hacking', 'Ethical Hacking', 'Ethical Hacking introduces authorized security assessment techniques used to identify system vulnerabilities. Students study reconnaissance concepts, vulnerability assessment, security testing methodologies, and responsible reporting. Practical work must take place in authorized laboratories or controlled environments. The course emphasizes permission, legal boundaries, documentation, and remediation rather than unauthorized access to real systems.', '', 'Cybersecurity', '100L', 'indigo', 'code', 'Faculty of Technology', 'Cybersecurity', '2026-11-02', 24500),
  ('faculty-of-technology-cybersecurity-100l-digital-forensics', 'Digital Forensics', 'Digital Forensics teaches students how digital evidence is identified, preserved, examined, and documented during investigations. Topics include evidence integrity, forensic imaging, file-system analysis, metadata, event logs, and investigation procedures. Students learn why accurate documentation and chain of custody matter, while considering privacy, legal requirements, and the limitations of forensic conclusions.', '', 'Cybersecurity', '100L', 'indigo', 'code', 'Faculty of Technology', 'Cybersecurity', '2026-11-02', 25000),
  ('faculty-of-technology-cybersecurity-100l-identity-and-access-management', 'Identity and Access Management', 'Identity and Access Management examines how organizations control who can access systems and information. Students study authentication, authorization, multifactor authentication, role-based access control, single sign-on, and account lifecycle management. Practical activities involve designing access policies, applying least-privilege principles, and reviewing permissions to reduce unauthorized access and improve accountability.', '', 'Cybersecurity', '100L', 'indigo', 'code', 'Faculty of Technology', 'Cybersecurity', '2026-11-02', 25500),
  ('faculty-of-technology-cybersecurity-100l-security-operations', 'Security Operations', 'Security Operations focuses on monitoring systems and responding to cybersecurity incidents. Students learn about security information and event management, log analysis, alert investigation, incident classification, and response procedures. Practical exercises use simulated events to identify suspicious activity, document findings, and recommend defensive actions that support an organization''s ability to detect and manage threats.', '', 'Cybersecurity', '100L', 'indigo', 'code', 'Faculty of Technology', 'Cybersecurity', '2026-11-02', 26000),
  ('faculty-of-technology-cybersecurity-100l-risk-management-and-compliance', 'Risk Management and Compliance', 'This course introduces methods for identifying, assessing, and managing information security risks. Students examine risk registers, security policies, control assessments, privacy requirements, and compliance frameworks. They learn to evaluate potential business impacts, recommend appropriate safeguards, and document decisions. The course connects technical security measures with organizational responsibilities and governance.', '', 'Cybersecurity', '100L', 'indigo', 'code', 'Faculty of Technology', 'Cybersecurity', '2026-11-02', 26500),
  ('faculty-of-technology-cloud-computing-100l-cloud-infrastructure', 'Cloud Infrastructure', 'Cloud Infrastructure introduces the computing resources used to run applications in cloud environments. Students learn about virtual machines, compute instances, storage, networking, availability, and resource provisioning. Practical exercises involve creating and configuring basic cloud resources, monitoring their usage, and understanding how organizations scale infrastructure to meet changing application requirements.', '', 'Cloud Computing', '100L', 'indigo', 'code', 'Faculty of Technology', 'Cloud Computing', '2026-11-02', 27000),
  ('faculty-of-technology-cloud-computing-100l-cloud-architecture', 'Cloud Architecture', 'Cloud Architecture teaches students how to design reliable, secure, and scalable systems using cloud services. Topics include architectural patterns, high availability, fault tolerance, load balancing, disaster recovery, and service selection. Students develop simple architecture diagrams and evaluate design trade-offs, learning how to match cloud resources to application needs and operational requirements.', '', 'Cloud Computing', '100L', 'indigo', 'code', 'Faculty of Technology', 'Cloud Computing', '2026-11-02', 27500),
  ('faculty-of-technology-cloud-computing-100l-cloud-networking', 'Cloud Networking', 'Cloud Networking examines how networks are designed and configured within cloud platforms. Students study virtual networks, subnets, routing, gateways, firewalls, private connectivity, and network access controls. Practical activities involve connecting cloud resources securely and troubleshooting connectivity issues, helping learners understand how cloud networking supports communication between applications, users, and external systems.', '', 'Cloud Computing', '100L', 'indigo', 'code', 'Faculty of Technology', 'Cloud Computing', '2026-11-02', 28000),
  ('faculty-of-technology-cloud-computing-100l-cloud-security', 'Cloud Security', 'Cloud Security focuses on protecting cloud-hosted resources, workloads, and information. Students study identity permissions, encryption, security groups, network controls, secrets management, monitoring, and incident response. The course explores secure configuration and shared responsibility between cloud providers and customers, helping learners identify common risks and apply appropriate safeguards to cloud environments.', '', 'Cloud Computing', '100L', 'indigo', 'code', 'Faculty of Technology', 'Cloud Computing', '2026-11-02', 28500),
  ('faculty-of-technology-cloud-computing-100l-cloud-storage', 'Cloud Storage', 'Cloud Storage teaches students how to store, retrieve, protect, and manage data using cloud services. Topics include object storage, block storage, file storage, backups, replication, lifecycle policies, and access permissions. Practical exercises compare storage options for different workloads, emphasizing durability, availability, performance, security, and cost when selecting suitable storage solutions.', '', 'Cloud Computing', '100L', 'indigo', 'code', 'Faculty of Technology', 'Cloud Computing', '2026-11-02', 29000),
  ('faculty-of-technology-cloud-computing-100l-serverless-computing', 'Serverless Computing', 'Serverless Computing introduces application development using managed cloud services that reduce the need to administer servers directly. Students explore event-driven functions, managed databases, triggers, permissions, and service integration. Practical projects demonstrate how applications respond to events and scale with demand, while covering execution limits, observability, reliability, and cost considerations.', '', 'Cloud Computing', '100L', 'indigo', 'code', 'Faculty of Technology', 'Cloud Computing', '2026-11-02', 29500),
  ('faculty-of-technology-cloud-computing-100l-cloud-databases', 'Cloud Databases', 'Cloud Databases examines database services hosted and managed through cloud platforms. Students learn about relational and non-relational databases, provisioning, backups, replication, scaling, access control, and performance monitoring. Practical exercises involve creating a database, connecting an application, and applying basic security measures while comparing managed services with self-managed database deployments.', '', 'Cloud Computing', '100L', 'indigo', 'code', 'Faculty of Technology', 'Cloud Computing', '2026-11-02', 30000),
  ('faculty-of-technology-cloud-computing-100l-cloud-cost-management', 'Cloud Cost Management', 'Cloud Cost Management teaches students how to monitor and control spending on cloud resources. Topics include pricing models, budgets, cost allocation tags, usage reports, resource optimization, and billing alerts. Learners examine example cloud bills and identify unnecessary expenditure, developing practical strategies for balancing cost, performance, availability, and organizational requirements.', '', 'Cloud Computing', '100L', 'indigo', 'code', 'Faculty of Technology', 'Cloud Computing', '2026-11-02', 30500),
  ('faculty-of-technology-devops-and-site-reliability-engineering-100l-continuous-integration-and-delivery-ci-cd', 'Continuous Integration and Delivery (CI/CD)', 'This course teaches students how to automate software building, testing, and deployment. Learners explore source control, automated test pipelines, build processes, deployment stages, and release management. Practical projects connect a code repository to a pipeline that validates changes before deployment, improving consistency, reducing manual work, and helping teams deliver software more frequently.', '', 'DevOps and Site Reliability Engineering', '100L', 'indigo', 'code', 'Faculty of Technology', 'DevOps and Site Reliability Engineering', '2026-11-02', 31000),
  ('faculty-of-technology-devops-and-site-reliability-engineering-100l-infrastructure-as-code', 'Infrastructure as Code', 'Infrastructure as Code teaches students to manage computing infrastructure through version-controlled configuration files instead of manual setup. Topics include declarative definitions, reusable modules, state management, environment consistency, and change review. Practical exercises provision sample infrastructure and demonstrate how automation improves repeatability, auditability, collaboration, and recovery from configuration errors.', '', 'DevOps and Site Reliability Engineering', '100L', 'indigo', 'code', 'Faculty of Technology', 'DevOps and Site Reliability Engineering', '2026-11-02', 31500),
  ('faculty-of-technology-devops-and-site-reliability-engineering-100l-containerization', 'Containerization', 'Containerization introduces the packaging of applications and their dependencies into portable execution environments. Students learn container images, registries, container runtimes, networking, volumes, and configuration. Practical exercises package an application into a container and run it consistently across environments, while covering image maintenance, resource management, and basic container security.', '', 'DevOps and Site Reliability Engineering', '100L', 'indigo', 'code', 'Faculty of Technology', 'DevOps and Site Reliability Engineering', '2026-11-02', 32000),
  ('faculty-of-technology-devops-and-site-reliability-engineering-100l-container-orchestration', 'Container Orchestration', 'Container Orchestration teaches students how to manage containerized applications across multiple machines. Topics include deployments, services, scheduling, scaling, health checks, configuration, and workload recovery. Students explore orchestration platforms such as Kubernetes and practise deploying a sample application, helping them understand how automated systems maintain application availability and manage changing workloads.', '', 'DevOps and Site Reliability Engineering', '100L', 'indigo', 'code', 'Faculty of Technology', 'DevOps and Site Reliability Engineering', '2026-11-02', 32500),
  ('faculty-of-technology-devops-and-site-reliability-engineering-100l-configuration-management', 'Configuration Management', 'Configuration Management focuses on keeping systems consistently configured across development, testing, and production environments. Students learn configuration files, automated provisioning, reusable playbooks, version control, and configuration drift detection. Practical exercises automate common administration tasks and standardize system settings, reducing manual errors and improving reliability, security, and operational efficiency.', '', 'DevOps and Site Reliability Engineering', '100L', 'indigo', 'code', 'Faculty of Technology', 'DevOps and Site Reliability Engineering', '2026-11-02', 33000),
  ('faculty-of-technology-devops-and-site-reliability-engineering-100l-monitoring-and-logging', 'Monitoring and Logging', 'Monitoring and Logging teaches students how to understand application and infrastructure behaviour through collected metrics, logs, and traces. Topics include dashboards, alert rules, log aggregation, service health, and troubleshooting. Practical activities investigate simulated failures and identify performance problems, helping learners use operational evidence to maintain availability and improve the user experience.', '', 'DevOps and Site Reliability Engineering', '100L', 'indigo', 'code', 'Faculty of Technology', 'DevOps and Site Reliability Engineering', '2026-11-02', 33500),
  ('faculty-of-technology-devops-and-site-reliability-engineering-100l-automation-and-scripting', 'Automation and Scripting', 'Automation and Scripting introduces the use of programming and command-line tools to automate repetitive technical tasks. Students learn variables, conditions, loops, functions, file operations, error handling, and scheduled execution using suitable scripting languages. Projects automate backups, report generation, system checks, and deployment tasks, improving productivity and reducing avoidable manual mistakes.', '', 'DevOps and Site Reliability Engineering', '100L', 'indigo', 'code', 'Faculty of Technology', 'DevOps and Site Reliability Engineering', '2026-11-02', 34000),
  ('faculty-of-technology-devops-and-site-reliability-engineering-100l-site-reliability-engineering-sre', 'Site Reliability Engineering (SRE)', 'Site Reliability Engineering applies software engineering practices to operating reliable services. Students study service-level indicators, service-level objectives, error budgets, incident management, capacity planning, and post-incident reviews. Practical exercises assess service reliability and investigate simulated outages, helping learners balance system stability with development speed while using measurable objectives to guide improvements.', '', 'DevOps and Site Reliability Engineering', '100L', 'indigo', 'code', 'Faculty of Technology', 'DevOps and Site Reliability Engineering', '2026-11-02', 34500),
  ('faculty-of-technology-data-science-and-analytics-100l-data-analysis', 'Data Analysis', 'Data Analysis teaches students to transform raw data into meaningful information. Learners study data cleaning, filtering, grouping, descriptive statistics, exploratory analysis, and interpretation. Practical exercises use spreadsheets, SQL, or programming tools to answer questions from datasets, identify trends, and communicate findings clearly while recognizing missing information, bias, and data-quality problems.', '', 'Data Science and Analytics', '100L', 'indigo', 'code', 'Faculty of Technology', 'Data Science and Analytics', '2026-11-02', 35000),
  ('faculty-of-technology-data-science-and-analytics-100l-data-engineering', 'Data Engineering', 'Data Engineering focuses on building systems that collect, transform, store, and deliver data for analysis. Students explore data pipelines, extraction and transformation, batch processing, streaming, data quality, and workflow scheduling. Projects demonstrate how to combine data from different sources into reliable datasets, while emphasizing scalability, documentation, monitoring, and maintainability.', '', 'Data Science and Analytics', '100L', 'indigo', 'code', 'Faculty of Technology', 'Data Science and Analytics', '2026-11-02', 35500),
  ('faculty-of-technology-data-science-and-analytics-100l-business-intelligence', 'Business Intelligence', 'Business Intelligence teaches students to turn organizational data into reports and decision-support tools. Topics include key performance indicators, dashboard design, reporting, data modelling, and business metrics. Practical activities create reports that help organizations track sales, costs, operations, and customer activity, emphasizing accurate interpretation and clear presentation for decision-makers.', '', 'Data Science and Analytics', '100L', 'indigo', 'code', 'Faculty of Technology', 'Data Science and Analytics', '2026-11-02', 36000),
  ('faculty-of-technology-data-science-and-analytics-100l-statistical-analysis', 'Statistical Analysis', 'Statistical Analysis introduces mathematical methods for understanding data and drawing evidence-based conclusions. Students study probability, distributions, sampling, estimation, hypothesis testing, correlation, and regression. Practical exercises analyse real or simulated datasets and interpret results carefully, helping learners distinguish meaningful relationships from coincidence and understand uncertainty when making decisions.', '', 'Data Science and Analytics', '100L', 'indigo', 'code', 'Faculty of Technology', 'Data Science and Analytics', '2026-11-02', 36500),
  ('faculty-of-technology-data-science-and-analytics-100l-data-visualization', 'Data Visualization', 'Data Visualization teaches students how to communicate information through charts, graphs, maps, and interactive dashboards. Learners explore visual encoding, chart selection, colour accessibility, layout, and storytelling with data. Practical assignments transform datasets into clear visual explanations, helping audiences recognize patterns, compare values, and understand findings without misleading representations.', '', 'Data Science and Analytics', '100L', 'indigo', 'code', 'Faculty of Technology', 'Data Science and Analytics', '2026-11-02', 37000),
  ('faculty-of-technology-data-science-and-analytics-100l-big-data', 'Big Data', 'Big Data introduces technologies and methods for processing datasets too large, fast, or complex for conventional approaches. Students explore distributed storage, parallel processing, data pipelines, batch workloads, and streaming systems. Practical activities examine how distributed platforms process large datasets, while considering data quality, scalability, privacy, reliability, and processing costs.', '', 'Data Science and Analytics', '100L', 'indigo', 'code', 'Faculty of Technology', 'Data Science and Analytics', '2026-11-02', 37500),
  ('faculty-of-technology-data-science-and-analytics-100l-data-warehousing', 'Data Warehousing', 'Data Warehousing teaches students how to organize integrated data for reporting and analysis. Topics include warehouse architecture, fact and dimension tables, star schemas, data transformation, and refresh strategies. Students design simple analytical data models and load information from operational sources, learning how consistent structures support reporting, historical comparisons, and business intelligence.', '', 'Data Science and Analytics', '100L', 'indigo', 'code', 'Faculty of Technology', 'Data Science and Analytics', '2026-11-02', 38000),
  ('faculty-of-technology-data-science-and-analytics-100l-data-governance', 'Data Governance', 'Data Governance examines the policies and responsibilities required to manage data properly throughout its lifecycle. Students study data ownership, quality standards, classification, access permissions, privacy, metadata, and retention. Practical exercises create governance rules for sample datasets, helping learners improve consistency, accountability, security, and appropriate use of organizational information.', '', 'Data Science and Analytics', '100L', 'indigo', 'code', 'Faculty of Technology', 'Data Science and Analytics', '2026-11-02', 38500),
  ('faculty-of-technology-artificial-intelligence-and-machine-learning-100l-machine-learning', 'Machine Learning', 'Machine Learning teaches students how computer systems learn patterns from data to make predictions or decisions. Topics include supervised and unsupervised learning, classification, regression, clustering, feature engineering, and model evaluation. Practical exercises train and test introductory models, helping learners understand data splitting, overfitting, accuracy measures, and responsible interpretation of predictions.', '', 'Artificial Intelligence and Machine Learning', '100L', 'indigo', 'code', 'Faculty of Technology', 'Artificial Intelligence and Machine Learning', '2026-11-02', 39000),
  ('faculty-of-technology-artificial-intelligence-and-machine-learning-100l-deep-learning', 'Deep Learning', 'Deep Learning introduces neural networks with multiple processing layers for learning complex patterns. Students explore network structure, activation functions, loss functions, optimization, training data, and model evaluation. Practical exercises use suitable machine-learning libraries to build introductory models, while discussing computing requirements, overfitting, interpretability, and the importance of representative training datasets.', '', 'Artificial Intelligence and Machine Learning', '100L', 'indigo', 'code', 'Faculty of Technology', 'Artificial Intelligence and Machine Learning', '2026-11-02', 39500),
  ('faculty-of-technology-artificial-intelligence-and-machine-learning-100l-natural-language-processing', 'Natural Language Processing', 'Natural Language Processing focuses on enabling computers to process and interpret human language. Students explore text preprocessing, tokenization, language classification, sentiment analysis, information extraction, and language modelling. Practical projects analyse text datasets or build simple language tools, while considering ambiguity, language diversity, privacy, and the risk of biased or inaccurate outputs.', '', 'Artificial Intelligence and Machine Learning', '100L', 'indigo', 'code', 'Faculty of Technology', 'Artificial Intelligence and Machine Learning', '2026-11-02', 40000),
  ('faculty-of-technology-artificial-intelligence-and-machine-learning-100l-computer-vision', 'Computer Vision', 'Computer Vision teaches students how computers analyse images and video to identify useful information. Topics include image processing, feature extraction, image classification, object detection, and evaluation methods. Practical activities use sample images to build or test vision models, while discussing image quality, privacy, fairness, and the limitations of automated visual recognition.', '', 'Artificial Intelligence and Machine Learning', '100L', 'indigo', 'code', 'Faculty of Technology', 'Artificial Intelligence and Machine Learning', '2026-11-02', 40500),
  ('faculty-of-technology-artificial-intelligence-and-machine-learning-100l-generative-ai', 'Generative AI', 'Generative AI introduces systems that create text, images, audio, code, and other forms of content. Students explore language models, image generation, prompts, retrieval-supported generation, output evaluation, and practical applications. The course also examines hallucinations, intellectual property, privacy, bias, and responsible use, emphasizing human review when generated content affects important decisions.', '', 'Artificial Intelligence and Machine Learning', '100L', 'indigo', 'code', 'Faculty of Technology', 'Artificial Intelligence and Machine Learning', '2026-11-02', 41000),
  ('faculty-of-technology-artificial-intelligence-and-machine-learning-100l-robotics-and-intelligent-systems', 'Robotics and Intelligent Systems', 'This course explores machines and software that sense their environments, make decisions, and perform actions. Students study sensors, control algorithms, navigation, perception, planning, and basic autonomous behaviour. Practical projects may use simulations or simple robotic platforms, helping learners understand how software, hardware, and intelligent decision-making combine to perform tasks.', '', 'Artificial Intelligence and Machine Learning', '100L', 'indigo', 'code', 'Faculty of Technology', 'Artificial Intelligence and Machine Learning', '2026-11-02', 41500),
  ('faculty-of-technology-artificial-intelligence-and-machine-learning-100l-speech-recognition', 'Speech Recognition', 'Speech Recognition teaches students how computers convert spoken language into machine-readable text or commands. Topics include audio signals, feature extraction, acoustic modelling, speech-to-text systems, and evaluation. Practical exercises examine recorded speech or existing recognition tools, while considering accents, background noise, accessibility, language coverage, and privacy in voice-enabled applications.', '', 'Artificial Intelligence and Machine Learning', '100L', 'indigo', 'code', 'Faculty of Technology', 'Artificial Intelligence and Machine Learning', '2026-11-02', 42000),
  ('faculty-of-technology-artificial-intelligence-and-machine-learning-100l-ai-ethics-and-governance', 'AI Ethics and Governance', 'AI Ethics and Governance examines the social, legal, and organizational responsibilities associated with intelligent systems. Students explore fairness, transparency, accountability, privacy, explainability, human oversight, and risk assessment. Case studies help learners identify potential harms and develop safeguards, ensuring AI applications are evaluated not only for performance but also for their effects on people.', '', 'Artificial Intelligence and Machine Learning', '100L', 'indigo', 'code', 'Faculty of Technology', 'Artificial Intelligence and Machine Learning', '2026-11-02', 42500),
  ('faculty-of-technology-computer-networking-100l-network-administration', 'Network Administration', 'Network Administration teaches students how to configure, operate, and maintain computer networks. Topics include device management, IP addressing, user access, network services, backups, and troubleshooting. Practical exercises involve monitoring network health and resolving common connectivity issues, helping learners maintain reliable services, document configurations, and support users within an organization.', '', 'Computer Networking', '100L', 'indigo', 'code', 'Faculty of Technology', 'Computer Networking', '2026-11-02', 43000),
  ('faculty-of-technology-computer-networking-100l-routing-and-switching', 'Routing and Switching', 'Routing and Switching introduces the technologies that move data between devices and networks. Students study Ethernet, switching tables, IP routing, VLANs, routing protocols, and network segmentation. Practical laboratory activities configure sample network devices and test connectivity, helping learners understand how packets travel through networks and how segmentation supports performance and security.', '', 'Computer Networking', '100L', 'indigo', 'code', 'Faculty of Technology', 'Computer Networking', '2026-11-02', 43500),
  ('faculty-of-technology-computer-networking-100l-wireless-networking', 'Wireless Networking', 'Wireless Networking focuses on communication technologies that connect devices without physical network cables. Students study Wi-Fi standards, access points, radio frequency concepts, wireless authentication, coverage, interference, and encryption. Practical activities design and troubleshoot sample wireless networks, emphasizing signal quality, secure configuration, user capacity, and reliable connectivity in different environments.', '', 'Computer Networking', '100L', 'indigo', 'code', 'Faculty of Technology', 'Computer Networking', '2026-11-02', 44000),
  ('faculty-of-technology-computer-networking-100l-network-design', 'Network Design', 'Network Design teaches students how to plan network infrastructure around organizational requirements. Topics include topology, addressing schemes, segmentation, redundancy, capacity planning, security, and equipment selection. Students create network diagrams and design solutions for sample homes, campuses, or businesses, balancing reliability, performance, growth, and budget constraints while documenting their design decisions.', '', 'Computer Networking', '100L', 'indigo', 'code', 'Faculty of Technology', 'Computer Networking', '2026-11-02', 44500),
  ('faculty-of-technology-computer-networking-100l-network-protocols', 'Network Protocols', 'Network Protocols examines the rules that enable devices and applications to exchange information. Students explore TCP/IP, DNS, DHCP, HTTP, HTTPS, and other common protocols. Practical exercises inspect sample network communications and troubleshoot protocol-related problems, helping learners understand addressing, connection establishment, name resolution, and the interactions between network layers.', '', 'Computer Networking', '100L', 'indigo', 'code', 'Faculty of Technology', 'Computer Networking', '2026-11-02', 45000),
  ('faculty-of-technology-computer-networking-100l-network-monitoring', 'Network Monitoring', 'Network Monitoring teaches students how to observe network performance, availability, and traffic patterns. Topics include latency, packet loss, bandwidth utilization, device health, alerts, and diagnostic tools. Practical activities interpret monitoring dashboards and investigate simulated faults, helping learners identify emerging problems, establish performance baselines, and improve the reliability of network services.', '', 'Computer Networking', '100L', 'indigo', 'code', 'Faculty of Technology', 'Computer Networking', '2026-11-02', 45500),
  ('faculty-of-technology-computer-networking-100l-network-virtualization', 'Network Virtualization', 'Network Virtualization introduces software-based methods for creating and managing logical networks. Students study virtual switches, virtual networks, overlays, segmentation, and software-defined networking concepts. Practical exercises explore isolated network environments and virtual network configurations, demonstrating how virtualization improves flexibility, resource utilization, testing, and the management of complex infrastructure.', '', 'Computer Networking', '100L', 'indigo', 'code', 'Faculty of Technology', 'Computer Networking', '2026-11-02', 46000),
  ('faculty-of-technology-computer-networking-100l-telecommunications', 'Telecommunications', 'Telecommunications examines the technologies used to transmit voice, video, and data over communication systems. Students explore transmission media, cellular networks, fibre optics, wireless communication, modulation, and signal quality. The course introduces how communication infrastructure connects users and services, while examining bandwidth, latency, coverage, reliability, and emerging communication technologies.', '', 'Computer Networking', '100L', 'indigo', 'code', 'Faculty of Technology', 'Computer Networking', '2026-11-02', 46500),
  ('faculty-of-technology-database-technology-100l-relational-databases', 'Relational Databases', 'Relational Databases teaches students how to organize information into related tables. Topics include tables, rows, columns, primary keys, foreign keys, constraints, normalization, and SQL queries. Practical projects design databases and retrieve information using joins, filtering, and aggregation, helping learners maintain data consistency and support applications with structured storage requirements.', '', 'Database Technology', '100L', 'indigo', 'code', 'Faculty of Technology', 'Database Technology', '2026-11-02', 47000),
  ('faculty-of-technology-database-technology-100l-nosql-databases', 'NoSQL Databases', 'NoSQL Databases introduces non-relational approaches for storing data that may not fit traditional table structures. Students explore document, key-value, wide-column, and graph databases. Practical exercises model sample application data and perform basic queries, while comparing consistency, scalability, flexibility, and access patterns to determine when different database types are appropriate.', '', 'Database Technology', '100L', 'indigo', 'code', 'Faculty of Technology', 'Database Technology', '2026-11-02', 47500),
  ('faculty-of-technology-database-technology-100l-database-administration', 'Database Administration', 'Database Administration teaches students how to maintain database systems and ensure they operate reliably. Topics include user permissions, configuration, monitoring, backup scheduling, updates, performance checks, and troubleshooting. Practical activities administer a sample database and review its health, helping learners protect information, maintain availability, and document routine operational procedures.', '', 'Database Technology', '100L', 'indigo', 'code', 'Faculty of Technology', 'Database Technology', '2026-11-02', 48000),
  ('faculty-of-technology-database-technology-100l-database-design', 'Database Design', 'Database Design focuses on translating application requirements into well-structured data models. Students learn entity-relationship diagrams, entities, attributes, relationships, keys, normalization, and constraints. Practical projects design schemas for systems such as school registration or inventory management, reducing duplication and improving data integrity while preparing structures that can support changing requirements.', '', 'Database Technology', '100L', 'indigo', 'code', 'Faculty of Technology', 'Database Technology', '2026-11-02', 48500),
  ('faculty-of-technology-database-technology-100l-database-security', 'Database Security', 'Database Security teaches students how to protect stored information against unauthorized access, disclosure, and alteration. Topics include authentication, permissions, encryption, secure queries, auditing, backups, and data privacy. Practical exercises configure appropriate access controls and review common weaknesses, helping learners apply least-privilege principles and protect sensitive information throughout its lifecycle.', '', 'Database Technology', '100L', 'indigo', 'code', 'Faculty of Technology', 'Database Technology', '2026-11-02', 49000),
  ('faculty-of-technology-database-technology-100l-data-backup-and-recovery', 'Data Backup and Recovery', 'Data Backup and Recovery examines techniques for protecting information against accidental deletion, hardware failure, and service disruptions. Students study full and incremental backups, recovery objectives, replication, restoration testing, and disaster recovery planning. Practical exercises restore sample databases from backups, emphasizing verification, documentation, backup protection, and preparation for unexpected incidents.', '', 'Database Technology', '100L', 'indigo', 'code', 'Faculty of Technology', 'Database Technology', '2026-11-02', 49500),
  ('faculty-of-technology-database-technology-100l-database-performance-optimization', 'Database Performance Optimization', 'Database Performance Optimization teaches students how to improve the speed and efficiency of database operations. Topics include query analysis, indexing, execution plans, schema design, caching, and workload monitoring. Practical exercises identify slow queries and compare optimization strategies, helping learners reduce unnecessary processing and improve response times without compromising data correctness or security.', '', 'Database Technology', '100L', 'indigo', 'code', 'Faculty of Technology', 'Database Technology', '2026-11-02', 50000),
  ('faculty-of-technology-database-technology-100l-distributed-databases', 'Distributed Databases', 'Distributed Databases explores systems that store and process data across multiple servers or locations. Students study replication, partitioning, consistency, availability, fault tolerance, and distributed transactions. Practical examples illustrate how distributed systems handle growth and failures, while helping learners understand trade-offs involved in keeping information accessible and consistent across multiple locations.', '', 'Database Technology', '100L', 'indigo', 'code', 'Faculty of Technology', 'Database Technology', '2026-11-02', 50500),
  ('faculty-of-technology-ui-ux-and-digital-product-design-100l-user-interface-ui-design', 'User Interface (UI) Design', 'UI Design teaches students how to design the visual elements of digital products, including buttons, menus, forms, layouts, and navigation. Topics include typography, spacing, colour, visual hierarchy, consistency, and responsive layouts. Practical assignments create interface mockups and reusable components, helping learners communicate information clearly and support effective user interaction.', '', 'UI/UX and Digital Product Design', '100L', 'indigo', 'code', 'Faculty of Technology', 'UI/UX and Digital Product Design', '2026-11-02', 51000),
  ('faculty-of-technology-ui-ux-and-digital-product-design-100l-user-experience-ux-design', 'User Experience (UX) Design', 'UX Design examines the overall experience people have when using a product or service. Students learn user needs analysis, journey mapping, information architecture, usability principles, and experience evaluation. Projects investigate user problems and develop design solutions, helping learners reduce confusion, improve task completion, and create products that better match user expectations.', '', 'UI/UX and Digital Product Design', '100L', 'indigo', 'code', 'Faculty of Technology', 'UI/UX and Digital Product Design', '2026-11-02', 51500),
  ('faculty-of-technology-ui-ux-and-digital-product-design-100l-interaction-design', 'Interaction Design', 'Interaction Design focuses on how users and digital systems respond to one another. Students explore navigation patterns, feedback, transitions, states, error prevention, and interactive behaviours. Practical exercises design common workflows and prototype interactions, helping learners make interfaces predictable, understandable, and efficient across different devices and user contexts.', '', 'UI/UX and Digital Product Design', '100L', 'indigo', 'code', 'Faculty of Technology', 'UI/UX and Digital Product Design', '2026-11-02', 52000),
  ('faculty-of-technology-ui-ux-and-digital-product-design-100l-wireframing-and-prototyping', 'Wireframing and Prototyping', 'Wireframing and Prototyping teaches students how to represent and test product ideas before full development. Learners create low-fidelity layouts, interactive prototypes, navigation flows, and design specifications. Practical exercises use design tools to communicate requirements and gather feedback, reducing misunderstandings and allowing teams to identify usability problems early in the product lifecycle.', '', 'UI/UX and Digital Product Design', '100L', 'indigo', 'code', 'Faculty of Technology', 'UI/UX and Digital Product Design', '2026-11-02', 52500),
  ('faculty-of-technology-ui-ux-and-digital-product-design-100l-user-research', 'User Research', 'User Research introduces methods for understanding the people who will use a digital product. Students study interviews, surveys, observation, usability sessions, and research synthesis. Practical projects gather and interpret feedback to identify user needs and barriers, while emphasizing informed participation, privacy, inclusive research practices, and evidence-based design decisions.', '', 'UI/UX and Digital Product Design', '100L', 'indigo', 'code', 'Faculty of Technology', 'UI/UX and Digital Product Design', '2026-11-02', 53000),
  ('faculty-of-technology-ui-ux-and-digital-product-design-100l-usability-testing', 'Usability Testing', 'Usability Testing teaches students how to evaluate whether people can use a product to complete important tasks. Topics include test objectives, task design, participant selection, observation, issue severity, and findings reports. Practical exercises test prototypes or sample applications, helping learners identify confusion, measure task success, and recommend improvements based on evidence.', '', 'UI/UX and Digital Product Design', '100L', 'indigo', 'code', 'Faculty of Technology', 'UI/UX and Digital Product Design', '2026-11-02', 53500),
  ('faculty-of-technology-ui-ux-and-digital-product-design-100l-design-systems', 'Design Systems', 'Design Systems examines reusable visual rules and components that help teams maintain consistent interfaces. Students explore component libraries, design tokens, typography, colour standards, documentation, and accessibility guidelines. Practical projects create a small design system and apply it across multiple screens, improving collaboration, consistency, efficiency, and the maintainability of digital product interfaces.', '', 'UI/UX and Digital Product Design', '100L', 'indigo', 'code', 'Faculty of Technology', 'UI/UX and Digital Product Design', '2026-11-02', 54000),
  ('faculty-of-technology-ui-ux-and-digital-product-design-100l-accessibility-design', 'Accessibility Design', 'Accessibility Design teaches students how to make digital products usable by people with diverse abilities and needs. Topics include keyboard navigation, colour contrast, readable content, semantic structure, captions, and assistive technologies. Practical evaluations identify barriers and recommend improvements, helping learners create more inclusive experiences and understand accessibility standards and user diversity.', '', 'UI/UX and Digital Product Design', '100L', 'indigo', 'code', 'Faculty of Technology', 'UI/UX and Digital Product Design', '2026-11-02', 54500),
  ('faculty-of-technology-robotics-and-embedded-systems-100l-robotics-engineering', 'Robotics Engineering', 'Robotics Engineering introduces the design, programming, and operation of robots that perform physical tasks. Students explore mechanical structures, sensors, actuators, control systems, navigation, and robot programming. Practical projects may use simulated or educational robots, helping learners integrate hardware and software while considering precision, safety, reliability, and task requirements.', '', 'Robotics and Embedded Systems', '100L', 'indigo', 'code', 'Faculty of Technology', 'Robotics and Embedded Systems', '2026-11-02', 55000),
  ('faculty-of-technology-robotics-and-embedded-systems-100l-embedded-programming', 'Embedded Programming', 'Embedded Programming teaches students to develop software for dedicated computing devices inside larger products. Topics include resource constraints, input/output operations, interrupts, timing, memory management, and hardware interfaces. Practical exercises program microcontrollers to control simple devices, helping learners understand the relationship between software, electronic components, and real-time system behaviour.', '', 'Robotics and Embedded Systems', '100L', 'indigo', 'code', 'Faculty of Technology', 'Robotics and Embedded Systems', '2026-11-02', 55500),
  ('faculty-of-technology-robotics-and-embedded-systems-100l-microcontrollers', 'Microcontrollers', 'Microcontrollers examines compact integrated circuits used to control electronic devices. Students learn processor basics, memory, digital and analogue inputs, timers, communication interfaces, and peripheral control. Practical laboratory work connects microcontrollers to sensors and output devices, teaching learners to build simple control systems and troubleshoot interactions between code and hardware.', '', 'Robotics and Embedded Systems', '100L', 'indigo', 'code', 'Faculty of Technology', 'Robotics and Embedded Systems', '2026-11-02', 56000),
  ('faculty-of-technology-robotics-and-embedded-systems-100l-internet-of-things-iot', 'Internet of Things (IoT)', 'Internet of Things introduces connected devices that collect and exchange data over networks. Students explore sensors, embedded devices, connectivity, messaging protocols, cloud integration, and device management. Practical projects build a simple connected monitoring system, while addressing authentication, privacy, reliability, power consumption, and the security risks associated with internet-connected devices.', '', 'Robotics and Embedded Systems', '100L', 'indigo', 'code', 'Faculty of Technology', 'Robotics and Embedded Systems', '2026-11-02', 56500),
  ('faculty-of-technology-robotics-and-embedded-systems-100l-sensors-and-actuators', 'Sensors and Actuators', 'Sensors and Actuators teaches students how electronic systems detect physical conditions and produce actions. Topics include temperature, pressure, light, motion, and distance sensors, along with motors and other actuators. Practical activities connect components to controllers and interpret their signals, helping learners calibrate devices and build systems that respond to environmental changes.', '', 'Robotics and Embedded Systems', '100L', 'indigo', 'code', 'Faculty of Technology', 'Robotics and Embedded Systems', '2026-11-02', 57000),
  ('faculty-of-technology-robotics-and-embedded-systems-100l-control-systems', 'Control Systems', 'Control Systems examines how systems are regulated to achieve desired behaviour. Students study feedback, open-loop and closed-loop control, system response, stability, and introductory mathematical models. Practical exercises simulate or build simple control applications, helping learners understand how measurements guide corrective actions in machines, industrial processes, and automated devices.', '', 'Robotics and Embedded Systems', '100L', 'indigo', 'code', 'Faculty of Technology', 'Robotics and Embedded Systems', '2026-11-02', 57500),
  ('faculty-of-technology-robotics-and-embedded-systems-100l-industrial-automation', 'Industrial Automation', 'Industrial Automation focuses on technologies that automate manufacturing and operational processes. Topics include programmable logic controllers, sensors, actuators, industrial networks, and robotic systems used in production environments. The course examines efficiency, safety, quality, and integration challenges in automated industrial settings.', '', 'Robotics and Embedded Systems', '100L', 'indigo', 'code', 'Faculty of Technology', 'Robotics and Embedded Systems', '2026-11-02', 58000),
  ('faculty-of-technology-robotics-and-embedded-systems-100l-autonomous-systems', 'Autonomous Systems', 'Autonomous Systems examines how machines operate with limited human intervention. Students explore sensing, perception, decision-making, path planning, and navigation. Practical examples consider drones, self-driving vehicles, and autonomous robots, helping learners understand reliability, safety, and the challenges of operating in unpredictable environments.', '', 'Robotics and Embedded Systems', '100L', 'indigo', 'code', 'Faculty of Technology', 'Robotics and Embedded Systems', '2026-11-02', 58500),
  ('faculty-of-technology-information-technology-it-support-100l-computer-hardware', 'Computer Hardware', 'Computer Hardware introduces the physical components of computers and how they work together. Students study processors, memory, storage devices, motherboards, power supplies, peripherals, and assembly. Practical exercises involve identifying components, diagnosing faults, and performing basic upgrades and maintenance, helping learners understand compatibility, performance, and safe handling of hardware.', '', 'Information Technology (IT) Support', '100L', 'indigo', 'code', 'Faculty of Technology', 'Information Technology (IT) Support', '2026-11-02', 59000),
  ('faculty-of-technology-information-technology-it-support-100l-operating-system-support', 'Operating System Support', 'Operating System Support teaches students how to install, configure, update, and troubleshoot operating systems. Topics include user accounts, drivers, permissions, software installation, system settings, and recovery tools. Practical activities resolve common operating-system problems, helping learners support users, maintain security, and keep systems stable and productive.', '', 'Information Technology (IT) Support', '100L', 'indigo', 'code', 'Faculty of Technology', 'Information Technology (IT) Support', '2026-11-02', 59500),
  ('faculty-of-technology-information-technology-it-support-100l-it-help-desk', 'IT Help Desk', 'IT Help Desk introduces the practices used to receive, prioritise, document, and resolve user support requests. Students learn ticketing, communication, troubleshooting steps, escalation, and knowledge documentation. Practical scenarios develop professional support skills, helping learners diagnose issues efficiently and maintain positive relationships with the people they assist.', '', 'Information Technology (IT) Support', '100L', 'indigo', 'code', 'Faculty of Technology', 'Information Technology (IT) Support', '2026-11-02', 60000),
  ('faculty-of-technology-information-technology-it-support-100l-system-administration', 'System Administration', 'System Administration teaches students how to manage and maintain computer systems and servers. Topics include user accounts, permissions, updates, monitoring, storage, backups, and service configuration. Practical exercises administer sample systems and apply security and maintenance procedures, helping learners keep organizational systems available, secure, and well documented.', '', 'Information Technology (IT) Support', '100L', 'indigo', 'code', 'Faculty of Technology', 'Information Technology (IT) Support', '2026-11-02', 60500),
  ('faculty-of-technology-information-technology-it-support-100l-it-asset-management', 'IT Asset Management', 'IT Asset Management focuses on tracking and managing an organization''s technology assets throughout their lifecycle. Students study inventory records, procurement, licensing, assignment, maintenance, and disposal. Practical exercises maintain asset registers and review usage, helping learners control costs, support audits, plan replacements, and improve accountability for hardware and software.', '', 'Information Technology (IT) Support', '100L', 'indigo', 'code', 'Faculty of Technology', 'Information Technology (IT) Support', '2026-11-02', 61000),
  ('faculty-of-technology-information-technology-it-support-100l-technical-troubleshooting', 'Technical Troubleshooting', 'Technical Troubleshooting teaches students a structured approach to diagnosing and resolving technical problems. Topics include problem identification, information gathering, hypothesis testing, solution implementation, and verification. Practical exercises cover hardware, software, and network issues, helping learners work methodically, document solutions, and reduce repeat incidents.', '', 'Information Technology (IT) Support', '100L', 'indigo', 'code', 'Faculty of Technology', 'Information Technology (IT) Support', '2026-11-02', 61500),
  ('faculty-of-technology-information-technology-it-support-100l-it-service-management', 'IT Service Management', 'IT Service Management introduces frameworks and processes for delivering reliable technology services. Students study service levels, incident and problem management, change control, service requests, and continual improvement. Practical activities apply service-management practices to sample scenarios, helping learners align technology support with organizational needs and expectations.', '', 'Information Technology (IT) Support', '100L', 'indigo', 'code', 'Faculty of Technology', 'Information Technology (IT) Support', '2026-11-02', 62000),
  ('faculty-of-technology-information-technology-it-support-100l-backup-and-recovery', 'Backup and Recovery', 'Backup and Recovery teaches students how to protect data and restore systems after loss or failure. Topics include backup types, schedules, storage locations, retention, restoration procedures, and recovery testing. Practical exercises create backups and practise restores, helping learners reduce downtime, verify recoverability, and prepare for accidental deletion, corruption, or disasters.', '', 'Information Technology (IT) Support', '100L', 'indigo', 'code', 'Faculty of Technology', 'Information Technology (IT) Support', '2026-11-02', 62500),
  ('faculty-of-technology-blockchain-technology-100l-distributed-ledger-systems', 'Distributed Ledger Systems', 'Distributed Ledger Systems introduces shared digital records maintained across multiple network participants. Students explore ledger structure, transactions, cryptographic hashes, replication, validation, and differences between centralized and distributed databases. Practical exercises examine simplified ledger models, helping learners understand how shared records are updated, verified, and maintained across systems with multiple participants.', '', 'Blockchain Technology', '100L', 'indigo', 'code', 'Faculty of Technology', 'Blockchain Technology', '2026-11-02', 63000),
  ('faculty-of-technology-blockchain-technology-100l-smart-contract-development', 'Smart Contract Development', 'Smart Contract Development teaches students how to write programs that execute according to predefined rules on compatible blockchain platforms. Topics include contract structure, state, transactions, testing, deployment, and security considerations. Practical projects build simple demonstration contracts, emphasizing clear requirements, testing, permission design, and the importance of reviewing vulnerabilities before real-world use.', '', 'Blockchain Technology', '100L', 'indigo', 'code', 'Faculty of Technology', 'Blockchain Technology', '2026-11-02', 63500),
  ('faculty-of-technology-blockchain-technology-100l-decentralized-applications', 'Decentralized Applications', 'Decentralized Applications examines software that interacts with blockchain networks and smart contracts. Students explore user interfaces, wallet connections, transaction signing, contract integration, and decentralized data storage. Practical exercises build a simple demonstration application, helping learners understand how frontend components communicate with blockchain services and how usability, privacy, security, and transaction costs affect design.', '', 'Blockchain Technology', '100L', 'indigo', 'code', 'Faculty of Technology', 'Blockchain Technology', '2026-11-02', 64000),
  ('faculty-of-technology-blockchain-technology-100l-cryptocurrency-systems', 'Cryptocurrency Systems', 'Cryptocurrency Systems introduces the technical principles behind digital currencies that use cryptographic and distributed network mechanisms. Students study wallets, transactions, public and private keys, consensus, and blockchain records. The course focuses on system design and security rather than investment advice, while examining transaction verification, user responsibility, volatility, and common risks in digital financial systems.', '', 'Blockchain Technology', '100L', 'indigo', 'code', 'Faculty of Technology', 'Blockchain Technology', '2026-11-02', 64500),
  ('faculty-of-technology-blockchain-technology-100l-blockchain-security', 'Blockchain Security', 'Blockchain Security examines threats and safeguards associated with blockchain networks, smart contracts, and digital assets. Students study key management, access controls, contract vulnerabilities, transaction validation, and network-level risks. Practical exercises review simulated security scenarios and defensive design principles, emphasizing independent testing, secure development, responsible disclosure, and the limitations of relying on blockchain alone for protection.', '', 'Blockchain Technology', '100L', 'indigo', 'code', 'Faculty of Technology', 'Blockchain Technology', '2026-11-02', 65000),
  ('faculty-of-technology-blockchain-technology-100l-tokenization', 'Tokenization', 'Tokenization explores how digital tokens can represent assets, rights, or units of value within software systems. Students examine token standards, ownership records, transfer rules, and smart contract integration. Case studies consider possible applications in digital identity, supply chains, and record management, while addressing legal obligations, privacy, governance, and technical limitations.', '', 'Blockchain Technology', '100L', 'indigo', 'code', 'Faculty of Technology', 'Blockchain Technology', '2026-11-02', 65500),
  ('faculty-of-technology-blockchain-technology-100l-consensus-mechanisms', 'Consensus Mechanisms', 'Consensus Mechanisms teaches students how distributed systems agree on valid records or transactions. Topics include proof-based approaches, validator roles, fault tolerance, transaction ordering, and security assumptions. Students compare consensus designs and examine their effects on performance, decentralization, energy use, and resilience, developing a foundational understanding of how blockchain networks coordinate participants.', '', 'Blockchain Technology', '100L', 'indigo', 'code', 'Faculty of Technology', 'Blockchain Technology', '2026-11-02', 66000),
  ('faculty-of-technology-digital-media-and-creative-technology-100l-graphic-design', 'Graphic Design', 'Graphic Design teaches students how to communicate ideas through visual compositions. Topics include typography, colour theory, layout, branding, image editing, visual hierarchy, and design principles. Practical projects produce posters, logos, social media graphics, and other communication materials, helping learners develop creative problem-solving skills and create clear, audience-appropriate visual messages.', '', 'Digital Media and Creative Technology', '100L', 'indigo', 'code', 'Faculty of Technology', 'Digital Media and Creative Technology', '2026-11-02', 66500),
  ('faculty-of-technology-digital-media-and-creative-technology-100l-2d-and-3d-animation', '2D and 3D Animation', '2D and 3D Animation introduces techniques for creating movement in digital media. Students explore keyframes, timing, character movement, rigging, modelling, lighting, and rendering. Practical assignments produce short animated sequences using suitable software, helping learners understand storytelling, motion principles, production workflows, and the technical considerations involved in creating polished animations.', '', 'Digital Media and Creative Technology', '100L', 'indigo', 'code', 'Faculty of Technology', 'Digital Media and Creative Technology', '2026-11-02', 67000),
  ('faculty-of-technology-digital-media-and-creative-technology-100l-video-editing', 'Video Editing', 'Video Editing teaches students how to assemble recorded footage into coherent visual stories. Topics include timeline editing, trimming, transitions, audio synchronization, colour correction, titles, and export settings. Practical projects produce short edited pieces, helping learners understand pacing, story flow, shot selection, and the technical requirements of delivering polished video content.', '', 'Digital Media and Creative Technology', '100L', 'indigo', 'code', 'Faculty of Technology', 'Digital Media and Creative Technology', '2026-11-02', 67500),
  ('faculty-of-technology-digital-media-and-creative-technology-100l-motion-graphics', 'Motion Graphics', 'Motion Graphics focuses on animated text, shapes, diagrams, and visual elements used to communicate information. Students study composition, timing, typography, transitions, keyframes, and visual storytelling. Practical exercises create animated titles, explainers, or promotional sequences, helping learners combine graphic design and movement to make complex information more engaging and understandable.', '', 'Digital Media and Creative Technology', '100L', 'indigo', 'code', 'Faculty of Technology', 'Digital Media and Creative Technology', '2026-11-02', 68000),
  ('faculty-of-technology-digital-media-and-creative-technology-100l-3d-modelling', '3D Modelling', '3D Modelling teaches students how to create three-dimensional digital objects and environments. Topics include geometry, meshes, materials, textures, lighting, camera positioning, and rendering. Practical assignments build models for visualization, animation, or product concepts, helping learners understand object structure, modelling workflows, visual accuracy, and the technical requirements of digital production.', '', 'Digital Media and Creative Technology', '100L', 'indigo', 'code', 'Faculty of Technology', 'Digital Media and Creative Technology', '2026-11-02', 68500),
  ('faculty-of-technology-digital-media-and-creative-technology-100l-virtual-reality-vr', 'Virtual Reality (VR)', 'Virtual Reality introduces computer-generated environments designed to provide immersive experiences. Students explore spatial interaction, scene design, tracking, navigation, interface placement, and performance requirements. Practical projects create simple virtual environments or demonstrations, while considering accessibility, comfort, privacy, hardware limitations, and appropriate applications in education, training, simulation, and entertainment.', '', 'Digital Media and Creative Technology', '100L', 'indigo', 'code', 'Faculty of Technology', 'Digital Media and Creative Technology', '2026-11-02', 69000),
  ('faculty-of-technology-digital-media-and-creative-technology-100l-augmented-reality-ar', 'Augmented Reality (AR)', 'Augmented Reality teaches students how digital content can be placed within views of the physical world. Topics include tracking, spatial mapping, interactive overlays, mobile AR frameworks, and user experience. Practical activities develop simple AR demonstrations, helping learners connect digital objects with real environments while addressing usability, device compatibility, privacy, and safe interaction.', '', 'Digital Media and Creative Technology', '100L', 'indigo', 'code', 'Faculty of Technology', 'Digital Media and Creative Technology', '2026-11-02', 69500),
  ('faculty-of-technology-digital-media-and-creative-technology-100l-digital-audio-production', 'Digital Audio Production', 'Digital Audio Production teaches students how to record, edit, arrange, and mix audio using digital tools. Topics include sound capture, waveforms, audio tracks, effects, mixing, mastering, and export formats. Practical projects produce podcasts, voice recordings, or short audio pieces, emphasizing sound clarity, balanced levels, file organization, and responsible use of recorded material.', '', 'Digital Media and Creative Technology', '100L', 'indigo', 'code', 'Faculty of Technology', 'Digital Media and Creative Technology', '2026-11-02', 70000)
